def detect_duplicates(arr1, arr2):
    # create hash table to store elements from arr1
    hash_table = {}

    # iterate over arr1 and populate hash table
    for num in arr1:
        if num not in hash_table:
            hash_table[num] = 1
        else:
            return True

    # create hash table to store elements from arr2
    hash_table2 = {}

    # iterate over arr2 and populate hash table2
    for tup in arr2:
        if tup[0] not in hash_table2:
            hash_table2[tup[0]] = 1
        elif tup[1] not in hash_table2:
            hash_table2[tup[1]] = 1
        else:
            return True

    # no duplicates found
    return False

