def calculate_binary_search_trees(number):
    if number == 0 or number == 1:
        return 1
    result = 0
    for i in range(1, number + 1):
        left_subtrees = calculate_binary_search_trees(i - 1)
        right_subtrees = calculate_binary_search_trees(number - i)
        result += left_subtrees * right_subtrees
    return result

