def calculate_binary_search_trees(number):
    if number <= 1:
        return 1
    dp = [0] * (number + 1)
    dp[0], dp[1] = 1, 1
    for i in range(2, number + 1):
        for j in range(i):
            dp[i] += dp[j] * dp[i - j - 1]
    return dp[number]

