import re
from collections import defaultdict

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def filter_and_sort_strings(strings):
    primes = defaultdict(list)
    for s in strings:
        match = re.findall(r'\d+', s)
        for num in match:
            if is_prime(int(num)):
                primes[num].append(s)

    sorted_strings = []
    for primes_list in primes.values():
        sorted_strings.extend(sorted(primes_list))

    return sorted_strings

