def find_median(A, B):
    merged = []
    while A and B:
        if A[0] < B[0]:
            heapq.heappush(merged, A.pop(0))
        else:
            heapq.heappush(merged, B.pop(0))
    merged += A + B
    n = len(merged)
    return (merged[n//2 - 1] + merged[n//2]) / 2 if n % 2 == 0 else merged[n//2]

