def get_adjacent_numbers(matrix):
    rows = len(matrix)
    cols = len(matrix[0])
    result = set()

    # Horizontal adjacent numbers
    for i in range(rows):
        for j in range(cols - 1):
            result.add(matrix[i][j])
            result.add(matrix[i][j + 1])

    # Vertical adjacent numbers
    for i in range(rows - 1):
        for j in range(cols):
            result.add(matrix[i][j])
            result.add(matrix[i + 1][j])

    # Diagonal adjacent numbers (top-left to bottom-right)
    for i in range(rows - 1):
        for j in range(cols - 1):
            result.add(matrix[i][j])
            result.add(matrix[i + 1][j + 1])

    # Diagonal adjacent numbers (top-right to bottom-left)
    for i in range(rows - 1):
        for j in range(1, cols):
            result.add(matrix[i][j])
            result.add(matrix[i + 1][j - 1])

    return list(result)

