            # Horizontal adjacent
            if j < cols - 1:
                result.add(matrix[i][j + 1])
            # Vertical adjacent
            if i < rows - 1:
                result.add(matrix[i + 1][j])
            # Diagonal adjacent (top-left to bottom-right)
            if i > 0 and j < cols - 1:
                result.add(matrix[i - 1][j + 1])
            # Diagonal adjacent (top-right to bottom-left)
            if i > 0 and j > 0:
                result.add(matrix[i - 1][j - 1])

    return list(result)

