def removeComments(source):
    res, i, j, k = [], 0, 0, len(source)
    while i < k:
        if source[i][j:j+2] == '/*':
            j += 2
            while j < k and source[i][j:j+2] != '*/':
                j += 1
            if j >= k:
                break
            j += 2
        elif source[i][j:j+2] == '//':
            break
        else:
            j += 1
        if j == k:
            res.append(source[i])
            i += 1
            j = 0
    return res

