def shell_sort(collection):
    n = len(collection)
    gap = n // 2
    while gap > 0:
        for i in range(gap, n):
            temp = collection[i]
            j = i
            while j >= gap and collection[j - gap] > temp:
                collection[j] = collection[j - gap]
                j -= gap
            collection[j] = temp
        gap //= 2
    return collection

