def palindromic_substrings(s):
    n = len(s)
    dp = [[False] * n for _ in range(n)]
    res = []

    for i in range(n-1, -1, -1):
        for j in range(i, n):
            if s[i] == s[j]:
                if j-i <= 1 or dp[i+1][j-1]:
                    dp[i][j] = True
                    res.append([i, j])

    return res

