def maxString(input):
    max_len = 1
    current_len = 1
    start_index = 0
    end_index = 0

    for i in range(1, len(input)):
        if input[i] == input[i-1]:
            current_len += 1
            if current_len > max_len:
                max_len = current_len
                start_index = i - max_len + 1
                end_index = i
        else:
            current_len = 1

    return input[start_index:end_index+1]

