def selection_sort(arr):
    n = len(arr)
    swap_count = 0

    for i in range(n-1, 0, -1):
        max_value = arr[i]
        max_index = i

        for j in range(i-1, -1, -1):
            if arr[j] > max_value:
                max_value = arr[j]
                max_index = j

        if max_index != i:
            swap_count += 1
            arr[i], arr[max_index] = arr[max_index], arr[i]

    return arr, swap_count

