def generate_primes(limit):
    primes = []
    sieve = [True] * (limit + 1)
    sieve[0], sieve[1] = False, False

    for num in range(2, int(limit**0.5) + 1):
        if sieve[num]:
            for multiple in range(num*num, limit + 1, num):
                sieve[multiple] = False

    for num in range(2, limit + 1):
        if sieve[num]:
            primes.append(num)

    return primes

