    if n in computed:
        return computed[n]
    else:
        result = fibonacci(n-1, computed) + fibonacci(n-2, computed)
        computed[n] = result
        return result

def fibonacci(n, computed={0: 0, 1: 1}, i=2):
    if n in computed:
        return computed[n]
    else:
        result = fibonacci(i-1, computed) + fibonacci(i-2, computed)
        computed[i] = result
        if i == n:
            return result
        return fibonacci(n, computed, i+1)

