def find_common_prefix(str_list):
    if not str_list:
        return ""

    # Find the minimum length among all strings
    min_len = min(len(s) for s in str_list)

    # Initialize the common prefix as an empty string
    common_prefix = ""

    # Iterate through each character up to the minimum length
    for i in range(min_len):
        # Check if the current character is the same in all strings
        if all(s[i] == str_list[0][i] for s in str_list):
            common_prefix += str_list[0][i]
        else:
            break

    return common_prefix

