    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers.")
    elif n == 0 or n == 1:
        return 1
    elif n in memo:
        return memo[n]
    else:
        result = n * factorial(n - 1)
        memo[n] = result
        return result

