def root_to_leaf_util(root, curr_str):
    """How can I print all the paths from the root to the leaf in a given tree using Python?"""
    if root.left is None and root.right is None:  # If it's a leaf node
        print(curr_str + str(root.val))  # Print the current path
    else:
        root_to_leaf_util(root.left, curr_str + str(root.val) + "->")  # Recursively call for left child
        root_to_leaf_util(root.right, curr_str + str(root.val) + "->")  # Recursively call for right child

