def divide_and_conquer(string1, string2):
    if len(string1) == 0:
        return string2
    elif len(string2) == 0:
        return string1
    else:
        mid = len(string1) // 2
        left_half = divide_and_conquer(string1[:mid], string2)
        right_half = divide_and_conquer(string1[mid:], string2)
        return left_half + right_half

