import json

def schema_to_json(schema: dict, indent: int = 2) -> str:
    def process_type(type_):
        if type_ == 'string':
            return None
        elif type_ == 'integer':
            return 'number'
        elif type_ == 'array':
            return 'object'
        else:
            return type_

    def modify_schema(obj):
        if isinstance(obj, dict):
            for key, value in obj.items():
                if key == 'type':
                    obj[key] = process_type(value)
                else:
                    modify_schema(value)
        elif isinstance(obj, list):
            for i, item in enumerate(obj):
                modify_schema(item)

    modify_schema(schema)
    return json.dumps(schema, indent=indent)

