def find_swap_values(arr1: List[int], arr2: List[int]) -> List[int]:
    arr1.sort()
    arr2.sort(reverse=True)
    i = j = 0
    while i < len(arr1) and j < len(arr2):
        if arr1[i] + arr2[j] == sum(arr1) // 2:
            return [arr1[i], arr2[j]]
        elif arr1[i] + arr2[j] > sum(arr1) // 2:
            j += 1
        else:
            i += 1
    return []

