def max_min_product(nums):
    if not nums:
        return (0, 0)

    max_product = min_product = current_max = current_min = nums[0]

    for num in nums[1:]:
        if num < 0:
            current_max, current_min = current_min, current_max

        current_max = max(num, current_max * num)
        current_min = min(num, current_min * num)

        max_product = max(max_product, current_max)
        min_product = min(min_product, current_min)

    return (max_product, min_product)

def max_min_product(nums):
    if len(nums) == 0:
        return (0, 0)

    min_val = max_val = nums[0]
    min_neg = max_neg = nums[0]

    for num in nums[1:]:
        if num < 0:
            temp = min_val
            min_val = max(max_neg, num)
            max_neg = temp

        else:
            min_val = min(min_val * num, num)
            max_val = max(max_val * num, num)

        if num > max_neg:
            max_neg = num
        elif num < min_neg:
            min_neg = num

    return (max_val, min_neg)

