def find_longest_subarray_sum_equals_target(nums, target):
    prefix_sum = 0
    max_length = 0
    prefix_sum_dict = defaultdict(int)

    for i in range(len(nums)):
        prefix_sum += nums[i]

        if prefix_sum == target:
            max_length = i + 1

        if prefix_sum - target in prefix_sum_dict:
            max_length = max(max_length, i - prefix_sum_dict[prefix_sum - target])

        prefix_sum_dict[prefix_sum] = i

    return max_length

