import numpy as np

def determinant(matrix):
    return np.linalg.det(matrix)

def determinant(matrix):
    if len(matrix) == 1:
        return matrix[0][0]
    det = 0
    for i in range(len(matrix)):
        sub_matrix = [row[:i] + row[i+1:] for row in matrix[1:]]
        sign = (-1)**i
        det += sign * matrix[0][i] * determinant(sub_matrix)
    return det

